@startuml

class Company {
}

class Employee {
  + Name : string
  + SocialSecurityNumber : string
}

class Planner extends Employee {
  + Username : string
  + Password : string
}

class AdministrativeStaff extends Employee {
  + Username : string
  + Password : string
  + FieldOfActivity : string
}

class Driver extends Employee {
}

class Customer {
  + Name : string
  + BillingAddress : string
}

class PartnerCompany {
  + Name : string
  + Address : string
}

class Vehicle {
  + LicensePlate : string
  + Mileage : int
}

class RefrigeratedTruck extends Vehicle {}
class SmallVan extends Vehicle {}
class LoadingPlatform extends Vehicle {}
class BoxTruck extends Vehicle {}

class Repair {
  + Duration : string
  + Cost : float
}

class RepairShop {
  + Name : string
  + Address : string
}

class Order {
  + PackageSize : string
  + Comment : string
  + StartTime : datetime
  + FinishTime : datetime
  + PickUpAddress : string
  + DeliveryAddress : string
}

Company "1" -- "0..*" Employee
Company "1" -- "0..*" Customer
Company "1" -- "0..*" Vehicle
Company "1" -- "0..*" Order

Employee "0..*" -- "0..*" Repair : takes vehicle to
Repair "0..*" -- "1" Vehicle
Repair "0..*" -- "1" RepairShop

Order "0..*" -- "1" Customer : client
Order "0..*" -- "0..1" AdministrativeStaff : placed by
Order "0..*" -- "0..1" PartnerCompany : placed by
Order "0..*" -- "1" Planner : assigned by
Order "0..*" -- "1" Vehicle : assigned to
Order "0..*" -- "1" Driver : completed by
Order "0..*" -- "1" Driver : assigned to

@enduml

